<?php declare(strict_types=1);
use Kulturhus\Verein\Web\OccasionForm;
use Kulturhus\Native\Language\OccasionMessages;
$ot=static fn(string $text,array $values=[]):string=>OccasionMessages::text($text,$managerLanguageMessages??[], $values);
require __DIR__.'/../People/Members/people-navigation.php';
?>
<link rel="stylesheet" href="occasions.css">
<section class="list-page" data-occasions>
<?php
try{
 $occasionState=OccasionForm::query($occasionSavedQuery??$_GET);$isBirthday=$occasionState['kind']==='birthdays';$isFavourite=$occasionState['kind']==='favourites';$isAnniversary=$occasionState['kind']==='anniversaries';
 $title=$isBirthday?'Geburtstage':($isFavourite?'Favoriten':'Jubiläumsliste');$occasionBase=$occasionState['base'];$occasionQuery=$occasionState['q'];$occasionFrom=$occasionState['from'];$occasionTo=$occasionState['to'];
 if($isBirthday)$occasionRows=array_values(array_filter($registry->birthdayAgenda(date('Y-m-d')),static fn($c)=>$occasionQuery===''||mb_stripos($c['name'],$occasionQuery)!==false));
 elseif($isFavourite)$occasionRows=$registry->favouriteContacts($occasionQuery);
 else $occasionRows=$registry->anniversaries($occasionFrom,$occasionTo,$occasionQuery);
 $favouriteIds=$registry->favouriteIds();$rulesState=$registry->anniversaryRules();
 $occasionRuleName=static fn(string$name,int$months):string=>$rulesState['version']===0&&in_array($months,[12,60,120,240,300,360,480,600],true)?$ot($months===12?'1 Jahr':'{years} Jahre',['years'=>intdiv($months,12)]):$name;
 $occasionSize=$occasionState['size'];$occasionPages=max(1,(int)ceil(count($occasionRows)/$occasionSize));$occasionPage=$occasionState['page'];$occasionTotal=count($occasionRows);
 if($occasionPage>$occasionPages)throw new DomainException('Die ursprünglich gewählte Ergebnisseite ist nicht verfügbar. Suche und Seite bewusst neu wählen.',422);
 $occasionRows=array_slice($occasionRows,($occasionPage-1)*$occasionSize,$occasionSize);
}catch(DomainException $ex){if(http_response_code()<400)http_response_code(in_array($ex->getCode(),[403,404,409,503],true)?$ex->getCode():422); ?>
<div class="content"><h1><?=e($ot('Auswahl prüfen'))?></h1><p role="alert"><?=e($ot($ex->getMessage()))?></p><a class="btn btn-outline" href="<?=e(url(['view'=>'members','list'=>'birthdays']))?>"><?=e($ot('Geburtstage bewusst neu öffnen'))?></a><a class="btn btn-outline" href="<?=e(url(['view'=>'members-extra','tab'=>'anniversaries']))?>"><?=e($ot('Jubiläen bewusst neu öffnen'))?></a><a class="btn btn-outline" href="<?=e(url(['view'=>'contacts-extra','tab'=>'favourites']))?>"><?=e($ot('Favoriten bewusst neu öffnen'))?></a></div></section><?php return;}
?>
<div class="page-heading"><div class="heading-line"><h1><?=e($ot($title))?></h1><span class="count"><?=$occasionTotal?></span></div><?php if($isAnniversary&&$canWrite):?><a class="btn btn-solid theme-primary button" data-occasion-rules-open href="<?=e(url($occasionState['route']+['edit_rules'=>'1']))?>"><?=icon('plus')?> <?=e($ot('Jubiläumsregeln'))?></a><?php endif?></div>
<?php if($error!==''&&in_array($_POST['action']??null,OccasionForm::ACTIONS,true)):?><?php endif?>
<form method="get" class="book-filter occasion-filter"><?php foreach($occasionBase as$k=>$v)echo hidden($k,$v);?><label><?=e($ot('Name suchen'))?><input class="form-control" name="q" value="<?=e($occasionQuery)?>" maxlength="150"></label><?php if($isAnniversary):?><label><?=e($ot('Stichtag von'))?><input class="form-control" name="from" type="date" required value="<?=e($occasionFrom)?>"></label><label><?=e($ot('Stichtag bis'))?><input class="form-control" name="to" type="date" required value="<?=e($occasionTo)?>"></label><?php endif?><button class="btn btn-outline theme-secondary secondary"><?=e($ot('Filtern'))?></button></form>
<div class="table-scroll"><table class="table"><thead><tr><th><?=e($ot('Name'))?></th><?php if(!$isFavourite):?><th><?=e($ot('Nr.'))?></th><?php endif?><th><?=e($ot('E-Mail'))?></th><th><?=e($ot('Telefon'))?></th><?php if($isBirthday):?><th><?=e($ot('Geburtstag'))?></th><th><?=e($ot('Wird'))?></th><th><?=e($ot('Nächster Geburtstag'))?></th><?php elseif($isAnniversary):?><th><?=e($ot('Eintritt'))?></th><th><?=e($ot('Jubiläum'))?></th><th><?=e($ot('Stichtag'))?></th><?php endif?><th><?=e($ot('Favorit'))?></th></tr></thead><tbody>
<?php foreach($occasionRows as$c):?><tr><td data-label="<?=e($ot('Name'))?>"><a class="profile-link" href="<?=e(url(['view'=>'members','id'=>$c['id']]))?>"><?=e($c['name'])?></a></td><?php if(!$isFavourite):?><td data-label="<?=e($ot('Nr.'))?>"><?=e($c['member_number']?:'–')?></td><?php endif?><td data-label="<?=e($ot('E-Mail'))?>"><?=e($c['email']?:'–')?></td><td data-label="<?=e($ot('Telefon'))?>"><?=e($c['phone']?:'–')?></td><?php if($isBirthday):?><td data-label="<?=e($ot('Geburtstag'))?>"><?=e(dateDe($c['birthday']))?></td><td data-label="<?=e($ot('Wird'))?>"><span class="occasion-age"><?=$c['age']?></span></td><td data-label="<?=e($ot('Nächster Geburtstag'))?>"><?=e(dateDe($c['occasion_on']))?><small class="remaining-note"><?=e($ot(match($c['days']){0=>'Heute',1=>'Morgen',default=>'in {days} Tagen'},['days'=>$c['days']]))?></small></td><?php elseif($isAnniversary):?><td data-label="<?=e($ot('Eintritt'))?>"><?=e(dateDe($c['starts_on']))?></td><td data-label="<?=e($ot('Jubiläum'))?>"><span class="status passiv"><?=e($occasionRuleName($c['anniversary'],(int)$c['months']))?></span></td><td data-label="<?=e($ot('Stichtag'))?>"><?=e(dateDe($c['occasion_on']))?></td><?php endif?><td data-label="<?=e($ot('Favorit'))?>"><?php if($canWrite):$selected=in_array($c['id'],$favouriteIds,true);?><form method="post" action="<?=e(url($occasionState['route']))?>"><?=csrf().hidden('action','set-favourite').hidden('id',$c['id']).hidden('enabled',$selected?'0':'1').hidden('favourite_return',$occasionState['kind'])?><button class="btn btn-outline theme-secondary icon-button favourite-button <?=$selected?'is-favourite':''?>" aria-label="<?=e($ot($selected?'{name} aus Favoriten entfernen':'{name} als Favorit merken',['name'=>$c['name']]))?>" aria-pressed="<?=$selected?'true':'false'?>"><?=icon('star')?></button></form><?php endif?></td></tr><?php endforeach?>
<?php if(!$occasionRows):?><tr><td colspan="8" class="empty-state"><?=e($ot($isFavourite?'Noch keine Favoriten. Ein Profil öffnen und über den Stern merken.':($isBirthday?'Keine passenden Geburtstage. Suche und hinterlegte Geburtstage prüfen.':'Keine passenden Jubiläen im gewählten Zeitraum.')))?></td></tr><?php endif?></tbody></table></div>
<div class="table-footer"><form class="page-size-form" method="get"><?php foreach($occasionBase+['q'=>$occasionQuery]+($isAnniversary?['from'=>$occasionFrom,'to'=>$occasionTo]:[])as$k=>$v)echo hidden($k,$v);?><label><?=e($ot('Pro Seite'))?><select class="form-control" name="size"><?php foreach([20,40,100]as$n):?><option <?=$n===$occasionSize?'selected':''?>><?=$n?></option><?php endforeach?></select></label><button class="btn btn-outline theme-secondary secondary"><?=e($ot('Anzeigen'))?></button></form><nav class="pagination" aria-label="<?=e($ot('Ergebnisseiten'))?>"><span><?=e($ot('{page} von {pages}',['page'=>$occasionPage,'pages'=>$occasionPages]))?></span><?php foreach([-1=>'Vorherige Seite',1=>'Nächste Seite']as$delta=>$label):if($occasionPage+$delta<1||$occasionPage+$delta>$occasionPages)continue;?><a class="btn btn-outline" aria-label="<?=e($ot($label))?>" href="<?=e(url(array_replace($occasionState['route'],['page'=>(string)($occasionPage+$delta)])))?>"><?=$delta<0?'‹':'›'?></a><?php endforeach?></nav></div>
<div class="content"><p class="muted"><?=e($ot($isFavourite?'Favoriten sind persönlich und nur für deinen Zugang sichtbar.':($isBirthday?'Nach dem nächsten Geburtstag sortiert. Der 29. Februar wird in Jahren ohne Schalttag am 28. Februar angezeigt.':'Jubiläen aktiver und passiver Mitglieder beziehen sich auf den frühesten hinterlegten Eintritt. Monatsenden werden auf den letzten gültigen Kalendertag begrenzt.')))?></p></div>
<?php if($isAnniversary&&$canWrite&&($occasionState['edit']||($_POST['action']??null)==='save-anniversary-rules'))require __DIR__.'/../People/Members/anniversary-rules.php';?>
</section>
